-- =============================================
-- 87. 기출 문제 은행 — 문법 문항 태그 (sql/86 에서 뗀 문항 + 같이 읽은 문법 영역 문항)
-- 실행: node /Users/ara/Projects/Ara-system/scripts/run-sql.js sql/87_problem_bank_grammar_tags_detached.sql
-- =============================================
-- 배경(원장님 2026-11-06): "문법 트리에 태그를 넣어야 하는데 이건 태그 꼭 좀 넣어 주라." 뗀 문항은 지문·작품이 없어져
-- 문법 태그가 없으면 학교 기출 트리로만 찾힌다. 업체본 적재 때는 태그를 달지 않았다.
--
-- 규칙은 2026-10-12 원장 규칙 그대로다(grammar-rule.cjs 로 기계 검사): 한 가지에 하나면 잎 · 둘이면 두 잎 · 셋 이상이면
-- `<가지> > 혼합`, 중세 국어 자료는 그 안에만, 음운 변동 종합은 두 가지 모두 혼합, 선지 하나가 스치는 가지는 안 단다.
--
-- ⚠️ **읽고 정한 값이라 재계산할 수 없다**(sql/69 와 같은 성질). 지금 태그가 **빈 문항만** 채운다 — 이미 값이 있으면 덮지 않는다.
-- ⚠️ `grammar_paths` 는 패싯이 읽는 칸이라 캐시는 트리거가 따라온다. 스펙 JSON 에도 같은 값을 적었다.

BEGIN;

SET LOCAL search_path = exam, public;

CREATE TEMP TABLE _tags (
  id    UUID PRIMARY KEY,
  paths TEXT[] NOT NULL,
  note  TEXT NOT NULL
) ON COMMIT DROP;


DO $tags$
DECLARE
  v_total INT;
  v_done  INT;
  v_bad   INT;
BEGIN
  IF to_regclass('exam.problems') IS NULL THEN
    RAISE EXCEPTION 'exam.problems 가 없습니다 (현재 DB: %).', current_database();
  END IF;
  SELECT count(*) INTO v_total FROM _tags;

  UPDATE exam.problems p SET grammar_paths = t.paths
    FROM _tags t WHERE p.id = t.id AND cardinality(p.grammar_paths) = 0;
  GET DIAGNOSTICS v_done = ROW_COUNT;
  RAISE NOTICE '태그 단 문항 % / 이미 값이 있어 건너뜀 % (목록 %)', v_done, v_total - v_done, v_total;

  -- 검증 — 태그가 빈 채 남은 것이 없는가
  SELECT count(*) INTO v_bad FROM _tags t JOIN exam.problems p ON p.id = t.id WHERE cardinality(p.grammar_paths) = 0;
  IF v_bad > 0 THEN RAISE EXCEPTION '태그가 빈 문항 %건이 남았습니다.', v_bad; END IF;
END
$tags$;

SELECT exam.archive_facets_refresh();

COMMIT;
